var n=`0026-kutia`;var t=`world-0026`;var r=`UA`;var a=`eastern-europe`;var s=8;var o=103;var d={en:`Kutia`,ua:`Кутя`};var l={en:`A classic dish from Ukraine, featuring wheat berries, poppy seeds, walnut, raisin. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Україна. Основні складники: зерна пшениці, мак, волоський горіх, родзинки. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var g=[{en:`Cook the listed ingredients in simmering water for about 85 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 85 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:85,i:[[`wheat-berries`,240,`g`],[`water`,950,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:8,i:[[`poppy-seeds`,80,`g`],[`walnut`,90,`g`],[`honey`,120,`g`],[`raisin`,70,`g`]]},{en:`Chill briefly if appropriate, garnish with the listed ingredients and serve at the intended temperature.`,ua:`За потреби недовго охолодіть, прикрасьте зазначеними складниками й подавайте за потрібної температури.`,t:[`garnishing`],m:10,i:[[`uzvar-dried-fruit-mix`,90,`g`]]}];var u={slug:n,id:t,country:`UA`,region:a,servings:8,minutes:103,title:d,text:l,steps:g};export{r as country,u as default,t as id,o as minutes,a as region,s as servings,n as slug,g as steps,l as text,d as title};